    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Corriente de reposo para máxima excursión (ICQ)",
        "pregunta": "Calcule la corriente de reposo óptima $I_{CQ}$ (en mA).",
        "pistas": [
          "Pista 1: La resistencia total del lazo colector es $R_{dc} = R_C + R_E = 1.5\\text{ k}\\Omega + 0.5\\text{ k}\\Omega = 2.0\\text{ k}\\Omega$.",
          "Pista 2: Para excursión simétrica en continua: $I_{CQ} = \\frac{V_{CC} - V_{CE,sat}}{2 \\cdot R_{dc}}$.",
          "Pista 3: $I_{CQ} = \\frac{20 - 0.2}{2 \\cdot 2.0\\text{ k}\\Omega} = \\frac{19.8}{4.0} = 4.95\\text{ mA}$."
        ],
        "explicacion": "La condición de máxima excursión simétrica requiere posicionar el punto Q en el centro de la recta de carga activa: $I_{CQ} = \\frac{V_{CC} - V_{CE,sat}}{2(R_C + R_E)} = \\frac{20 - 0.2}{2(2.0\\text{ k}\\Omega)} = \\frac{19.8\\text{ V}}{4.0\\text{ k}\\Omega} = 4.95\\text{ mA}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mA",
        "solucion": 4.95,
        "valorEsperado": 4.95,
        "tolerancia": 0.05,
        "simbolo": "I_{CQ}",
        "explicacionPaso": "$I_{CQ} = \\frac{20 - 0.2}{2 \\times 2.0} = 4.95\\text{ mA}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Tensión colector-emisor de reposo (VCEQ)",
        "pregunta": "Determine la tensión colector-emisor en reposo $V_{CEQ}$ (en Volts).",
        "pistas": [
          "Pista 1: Por la recta de carga estática: $V_{CEQ} = V_{CC} - I_{CQ}(R_C + R_E)$.",
          "Pista 2: $V_{CEQ} = 20 - 4.95\\text{ mA} \\cdot 2.0\\text{ k}\\Omega = 20 - 9.9 = 10.1\\text{ V}$."
        ],
        "explicacion": "$V_{CEQ} = V_{CC} - I_{CQ}(R_C + R_E) = 20 - (4.95 \\cdot 2.0) = 20 - 9.90 = 10.1\\text{ V}$. Queda centrado exactamente entre $V_{CE,sat} = 0.2\\text{ V}$ y $V_{CC} = 20\\text{ V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 10.1,
        "valorEsperado": 10.1,
        "tolerancia": 0.05,
        "simbolo": "V_{CEQ}",
        "explicacionPaso": "$V_{CEQ} = 20 - 4.95(2.0) = 10.1\\text{ V}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Tensión pico máxima de salida sin recorte",
        "pregunta": "Calcule la amplitud pico máxima de salida sobre el colector $\\hat{v}_{o,max}$ (en Volts).",
        "pistas": [
          "Pista 1: La excursión pico hacia saturación es $V_{CEQ} - V_{CE,sat} = 10.1 - 0.2 = 9.9\\text{ V}$.",
          "Pista 2: La excursión pico hacia corte es $V_{CC} - V_{CEQ} = 20 - 10.1 = 9.9\\text{ V}$.",
          "Pista 3: En el colector respecto de masa la amplitud pico es $\\hat{i}_c \\cdot R_C = I_{CQ} \\cdot R_C = 4.95\\text{ mA} \\cdot 1.5\\text{ k}\\Omega = 7.425\\text{ V}$."
        ],
        "explicacion": "La amplitud pico máxima de corriente sin recorte es $\\hat{i}_c = I_{CQ} = 4.95\\text{ mA}$. Sobre la resistencia de colector $R_C = 1.5\\text{ k}\\Omega$, la tensión pico máxima es: $\\hat{v}_{o,max} = \\hat{i}_c \\cdot R_C = 4.95\\text{ mA} \\cdot 1.5\\text{ k}\\Omega \\approx 7.43\\text{ V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 7.43,
        "valorEsperado": 7.43,
        "tolerancia": 0.05,
        "simbolo": "\\hat{v}_{o,max}",
        "explicacionPaso": "$\\hat{v}_{o,max} = 4.95\\text{ mA} \\times 1.5\\text{ k}\\Omega = 7.43\\text{ V}$."
      }
    ]
